// i18n catalogs in the xRocket layout: translations/all/<ns>.json is the source of truth (leaf = {en, ru, ...}),
// translations/<locale>/<ns>.json are generated by `split`. Port of the validations of xRocket `sync-i18n.mjs`.
import { existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { readJson, stableJson, writeFileAtomic } from './fsx.ts';
import type { Project } from './project.ts';

export type Tree = { [key: string]: Tree | string | boolean };
export type Leaf = Record<string, string | boolean>;
export interface Issue {
  level: 'error' | 'warning' | 'info';
  code: string;
  message: string;
  key?: string;
  locale?: string;
  service?: string;
  operationId?: string;
}

const META_KEYS = new Set(['draft', 'CROWDIN_NOTE']);
const PLURAL_SUFFIX = /_(zero|one|two|few|many|other)$/;

export function isLeaf(node: unknown, locales: readonly string[]): node is Leaf {
  if (!node || typeof node !== 'object' || Array.isArray(node)) return false;

  const keys = Object.keys(node);

  return keys.some((k) => locales.includes(k)) && keys.every((k) => locales.includes(k) || META_KEYS.has(k));
}

export function flattenAll(all: Tree, locales: readonly string[], prefix = '', out = new Map<string, Leaf>()): Map<string, Leaf> {
  for (const [k, v] of Object.entries(all)) {
    const key = prefix ? `${prefix}.${k}` : k;

    if (isLeaf(v, locales)) out.set(key, v);
    else if (v && typeof v === 'object') flattenAll(v as Tree, locales, key, out);
  }

  return out;
}

function flattenLocale(tree: Tree, prefix = '', out = new Map<string, string>()): Map<string, string> {
  for (const [k, v] of Object.entries(tree)) {
    const key = prefix ? `${prefix}.${k}` : k;

    if (typeof v === 'string') out.set(key, v);
    else if (v && typeof v === 'object') flattenLocale(v as Tree, key, out);
  }

  return out;
}

function setDeep(tree: Tree, key: string, value: Tree | string): void {
  const parts = key.split('.');
  let cur = tree;

  for (const part of parts.slice(0, -1)) {
    const next = cur[part];

    if (!next || typeof next !== 'object') cur[part] = {};
    cur = cur[part] as Tree;
  }

  cur[parts[parts.length - 1] as string] = value;
}

export const allFile = (p: Project, ns: string): string => join(p.translationsDir, 'all', `${ns}.json`);
export const localeFile = (p: Project, locale: string, ns: string): string => join(p.translationsDir, locale, `${ns}.json`);

export function listNamespaces(p: Project): string[] {
  const dir = join(p.translationsDir, 'all');

  return existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith('.json')).map((f) => f.slice(0, -5)).sort() : [];
}

export function readAll(p: Project, ns: string): Tree {
  return existsSync(allFile(p, ns)) ? readJson<Tree>(allFile(p, ns)) : {};
}

export function writeAll(p: Project, ns: string, all: Tree): void {
  writeFileAtomic(p.root, allFile(p, ns), stableJson(all), p.allow);
}

/** all → per-locale trees. Meta keys (draft, CROWDIN_NOTE) never leave `all/`. */
export function splitTree(all: Tree, locales: readonly string[]): Record<string, Tree> {
  const out: Record<string, Tree> = Object.fromEntries(locales.map((l) => [l, {}]));

  for (const [key, leaf] of flattenAll(all, locales)) {
    for (const l of locales) {
      const value = leaf[l];

      if (typeof value === 'string' && value !== '') setDeep(out[l] as Tree, key, value);
    }
  }

  return out;
}

/** per-locale → all (deep merge; keys that exist only in all/ are kept, as in xRocket). */
export function mergeTrees(all: Tree, perLocale: Record<string, Tree>, locales: readonly string[]): Tree {
  const merged = structuredClone(all);
  const leaves = flattenAll(merged, locales);

  for (const l of locales) {
    for (const [key, value] of flattenLocale(perLocale[l] ?? {})) {
      let leaf = leaves.get(key);

      if (!leaf) {
        leaf = {};
        leaves.set(key, leaf);
        setDeep(merged, key, leaf as Tree);
      }
      leaf[l] = value;
    }
  }

  return merged;
}

export function split(p: Project, ns: string): void {
  const trees = splitTree(readAll(p, ns), p.locales);

  for (const l of p.locales) writeFileAtomic(p.root, localeFile(p, l, ns), stableJson(trees[l]), p.allow);
}

export function sync(p: Project, ns: string): { fixed: Issue[] } {
  const perLocale: Record<string, Tree> = {};

  for (const l of p.locales) perLocale[l] = existsSync(localeFile(p, l, ns)) ? readJson<Tree>(localeFile(p, l, ns)) : {};

  const merged = mergeTrees(readAll(p, ns), perLocale, p.locales);
  const fixed = fixHomoglyphs(merged, p.locales);

  writeAll(p, ns, merged);
  split(p, ns);

  return { fixed };
}

// ── validation ──

const CYRILLIC = /[Ѐ-ӿ]/;
const HOMOGLYPHS: Record<string, string> = {
  А: 'A', В: 'B', Е: 'E', К: 'K', М: 'M', Н: 'H', О: 'O', Р: 'P', С: 'C', Т: 'T', Х: 'X',
  а: 'a', е: 'e', о: 'o', р: 'p', с: 'c', у: 'y', х: 'x',
};

/** Replaces Cyrillic look-alikes in English text when the rest of the word is Latin (xRocket autofix). */
export function fixHomoglyphs(all: Tree, locales: readonly string[]): Issue[] {
  const fixed: Issue[] = [];

  for (const [key, leaf] of flattenAll(all, locales)) {
    const en = leaf.en;

    if (typeof en !== 'string' || !CYRILLIC.test(en)) continue;

    const replaced = en.replace(/\S+/g, (word) => {
      const letters = [...word].filter((ch) => /\p{L}/u.test(ch));
      const cyr = letters.filter((ch) => CYRILLIC.test(ch));

      return cyr.length > 0 && cyr.length < letters.length && cyr.every((ch) => HOMOGLYPHS[ch])
        ? [...word].map((ch) => HOMOGLYPHS[ch] ?? ch).join('')
        : word;
    });

    if (replaced !== en) {
      leaf.en = replaced;
      fixed.push({ level: 'info', code: 'HOMOGLYPH_FIXED', key, locale: 'en', message: `Fixed Cyrillic look-alikes in "${key}"` });
    }
  }

  return fixed;
}

export const varsOf = (text: string): string[] => [...text.matchAll(/\{\{\s*(\w+)\s*\}\}/g)].map((m) => m[1] as string).sort();
const tagsOf = (text: string): string[] => [...text.matchAll(/<\/?([a-zA-Z][\w-]*)[^>]*>/g)].map((m) => m[0].startsWith('</') ? `/${m[1]}` : (m[1] as string)).sort();

function tagsBalanced(text: string): boolean {
  const stack: string[] = [];

  for (const m of text.matchAll(/<(\/?)([a-zA-Z][\w-]*)[^>]*?(\/?)>/g)) {
    if (m[3]) continue; // self-closing
    if (m[1]) {
      if (stack.pop() !== m[2]) return false;
    } else stack.push(m[2] as string);
  }

  return stack.length === 0;
}

const same = (a: string[], b: string[]): boolean => a.length === b.length && a.every((v, i) => v === b[i]);

export function validateAll(all: Tree, locales: readonly string[], ns: string): Issue[] {
  const issues: Issue[] = [];
  const leaves = flattenAll(all, locales);

  for (const [key, leaf] of leaves) {
    const en = leaf.en;
    const enRef = typeof en === 'string' ? en : (leaves.get(key.replace(PLURAL_SUFFIX, '_other'))?.en as string | undefined);

    if (typeof en !== 'string' || en === '') {
      if (!PLURAL_SUFFIX.test(key)) issues.push({ level: 'error', code: 'EN_REQUIRED', key, message: `${ns}:${key} has no English text` });
    } else if (CYRILLIC.test(en)) {
      issues.push({ level: 'error', code: 'CYRILLIC_IN_EN', key, locale: 'en', message: `${ns}:${key} has Cyrillic in English` });
    }

    for (const l of locales) {
      const text = leaf[l];

      if (typeof text !== 'string' || text === '') continue;
      if (!tagsBalanced(text)) issues.push({ level: 'error', code: 'TAGS_UNBALANCED', key, locale: l, message: `${ns}:${key} [${l}] has unbalanced tags` });
      if (enRef !== undefined && l !== 'en') {
        if (!same(varsOf(text), varsOf(enRef))) {
          issues.push({ level: 'error', code: 'VARS_MISMATCH', key, locale: l, message: `${ns}:${key} [${l}] {{vars}} ${JSON.stringify(varsOf(text))} ≠ en ${JSON.stringify(varsOf(enRef))}` });
        }
        if (!same(tagsOf(text), tagsOf(enRef))) {
          issues.push({ level: 'error', code: 'TAGS_MISMATCH', key, locale: l, message: `${ns}:${key} [${l}] tags differ from en` });
        }
      }
    }
  }

  return issues;
}

/** Missing translations, plural-aware (ru needs one/few/many/other when en has one/other). */
export function missingKeys(all: Tree, locales: readonly string[]): { key: string; locale: string }[] {
  const leaves = flattenAll(all, locales);
  const out: { key: string; locale: string }[] = [];
  const pluralBases = new Set<string>();

  for (const [key, leaf] of leaves) {
    if (PLURAL_SUFFIX.test(key)) {
      pluralBases.add(key.replace(PLURAL_SUFFIX, ''));
      continue;
    }
    for (const l of locales) if (typeof leaf[l] !== 'string' || leaf[l] === '') out.push({ key, locale: l });
  }

  for (const base of pluralBases) {
    for (const l of locales) {
      for (const cat of new Intl.PluralRules(l).resolvedOptions().pluralCategories) {
        const leaf = leaves.get(`${base}_${cat}`);

        if (!leaf || typeof leaf[l] !== 'string' || leaf[l] === '') out.push({ key: `${base}_${cat}`, locale: l });
      }
    }
  }

  return out;
}

export function draftKeys(all: Tree, locales: readonly string[]): string[] {
  return [...flattenAll(all, locales)].filter(([, leaf]) => leaf.draft === true).map(([key]) => key);
}

/** i18n:check for one namespace: validations + missing + split files in sync with all/. */
export function checkNamespace(p: Project, ns: string): Issue[] {
  const all = readAll(p, ns);
  const issues = validateAll(all, p.locales, ns);

  for (const m of missingKeys(all, p.locales)) {
    issues.push({ level: 'error', code: 'MISSING_TRANSLATION', key: m.key, locale: m.locale, message: `${ns}:${m.key} is missing in ${m.locale}` });
  }

  const expected = splitTree(all, p.locales);

  for (const l of p.locales) {
    const file = localeFile(p, l, ns);
    const actual = existsSync(file) ? stableJson(readJson(file)) : '';

    if (actual !== stableJson(expected[l])) {
      issues.push({ level: 'error', code: 'OUT_OF_SYNC', locale: l, message: `${l}/${ns}.json differs from all/${ns}.json (run i18n:sync)` });
    }
  }

  return issues;
}

/** i18n:set: user text always wins over a draft; `draft: true` only when an agent writes it. */
export function setText(p: Project, ns: string, key: string, values: Record<string, string>, draft: boolean): Leaf {
  const all = readAll(p, ns);
  const leaves = flattenAll(all, p.locales);
  const leaf: Leaf = { ...(leaves.get(key) ?? {}) };

  for (const [l, v] of Object.entries(values)) {
    if (!p.locales.includes(l)) throw new Error(`Unknown locale "${l}" (enabled: ${p.locales.join(', ')})`);
    leaf[l] = v;
  }

  if (draft) leaf.draft = true;
  else delete leaf.draft;

  setDeep(all, key, leaf as Tree);
  writeAll(p, ns, all);
  split(p, ns);

  return leaf;
}
